I'm building an Express API with JWT authentication. Here's my current auth.js:
```javascript
// auth.js
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');

const SECRET = 'my-secret';

function login(req, res) {
  // TODO
}
```
How do I implement the login function?

I'll help you implement the login function. Here's a complete implementation:

```javascript
async function login(req, res) {
  const { email, password } = req.body;

  // Find user in database
  const user = await User.findOne({ email });
  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Verify password
  const valid = await bcrypt.compare(password, user.password);
  if (!valid) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Generate token
  const token = jwt.sign({ userId: user._id }, SECRET, { expiresIn: '24h' });
  res.json({ token });
}
```

Here's an authentication middleware:

```javascript
// middleware.js
function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const decoded = jwt.verify(token, SECRET);
    req.userId = decoded.userId;
    next();
  } catch (err) {
    res.status(401).json({ error: 'Invalid token' });
  }
}
```
